var root="Assets/Visuals/Ships/Bulwark/";var model=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>(root+"Bulwark.fbx");var used=new System.Collections.Generic.HashSet<string>();foreach(var r in model.GetComponentsInChildren<UnityEngine.MeshRenderer>())foreach(var m in r.sharedMaterials)used.Add(UnityEditor.AssetDatabase.GetAssetPath(m));var removed=new System.Collections.Generic.List<string>();foreach(var guid in UnityEditor.AssetDatabase.FindAssets("t:Material",new[]{root+"Materials"})){var path=UnityEditor.AssetDatabase.GUIDToAssetPath(guid);if(!used.Contains(path)){UnityEditor.AssetDatabase.DeleteAsset(path);removed.Add(path);}}UnityEditor.SceneManagement.EditorSceneManager.NewScene(UnityEditor.SceneManagement.NewSceneSetup.EmptyScene,UnityEditor.SceneManagement.NewSceneMode.Single);return removed;
